# find tandem repeats via simple k-mer period scan
def find_tandems(s, min_period=2, max_period=100, min_copies=3):
    hits=[]
    n=len(s)
    for p in range(min_period, max_period+1):
        i=0
        while i+p<=n:
            # try to extend
            j=i+p
            while j+p<=n and s[j:j+p]==s[i:i+p]:
                j+=p
            copies=(j-i)//p
            if copies>=min_copies and j-i>=30:
                hits.append((i+1, j, p, copies, s[i:j]))
                i=j
            else:
                i+=1
    return hits

