# ORFs on both strands (min 300 bp = 100 aa)
def orfs(s, strand, minlen=300):
    out=[]
    for f in range(3):
        i=f
        start=None
        while i+3<=len(s):
            cod=s[i:i+3]
            if start is None:
                if cod=='ATG': start=i
            else:
                if cod in ('TAA','TAG','TGA'):
                    if i+3-start>=minlen: out.append((start,i+3,strand))
                    start=None
            i+=3
        if start is not None and len(s)-start>=minlen:
            out.append((start,len(s),strand))
    return out

