seq=''.join(l.strip() for l in open('region.fasta') if not l.startswith('>'))
n=len(seq)

# tolerant tandem repeat detection: for each period p, slide and score windows
def hamming(a,b): return sum(x!=y for x,y in zip(a,b))
results=[]
for p in range(2,200):
    i=0
    while i+p<=n:
        # try to build a run starting at i
        j=i+p
        while j+p<=n:
            unit=seq[i:i+p]
            nxt=seq[j:j+p]
            if hamming(unit,nxt) <= max(1, p//15):
                j+=p
            else:
                break
        span=j-i
        if span>=2*p and span>=40:
            results.append((i+1,j,span,p,span//p))
            i=j
        else:
            i+=1
results.sort(key=lambda r:-r[2])
kept=[]
for r in results:
    if all(r[1]<=k[0] or r[0]>=k[1] for k in kept):
        kept.append(r)
print("Tandem repeats (tolerant), >=2 copies, >=40bp:")
for r in sorted(kept):
    print('  %d-%d  span=%d period=%d ~copies=%.1f'%(r[0],r[1],r[2],r[3],r[2]/r[3]))
    print('     ', seq[r[0]-1:r[0]-1+min(100,r[2])])

